// The one place crisis language is detected and answered. Every endpoint that
// accepts student text calls containsCrisisLanguage before any provider and,
// on a match, returns CRISIS_SUPPORT_RESPONSE instead of continuing the
// activity. The response is fixed text: it is never generated by a model.
//
// Detection is a phrase list, so it will miss some wording and over-match
// some. It leans toward over-matching: showing support resources to a student
// who did not need them costs less than missing one who did.

export type CrisisSupportResource = {
  readonly name: string;
  readonly contact: string;
};

export type CrisisSupportResponse = {
  readonly outcome: "support";
  readonly message: string;
  readonly resources: readonly CrisisSupportResource[];
};

// PLACEHOLDER WORDING: not yet approved by the sponsor. The resources and
// phone numbers are real (CAPS number checked against caps.sdes.ucf.edu on
// 2026-10-11); the sentences around them are a draft.
export const CRISIS_SUPPORT_RESPONSE: CrisisSupportResponse = Object.freeze({
  outcome: "support",
  message:
    "It sounds like you may be carrying something heavy right now. This activity is paused. You deserve support from a person, and help is available now.",
  resources: Object.freeze([
    Object.freeze({
      name: "988 Suicide & Crisis Lifeline",
      contact: "Call or text 988, any time.",
    }),
    Object.freeze({
      name: "UCF Counseling and Psychological Services (CAPS)",
      contact: "Call 407-823-2811. After hours, press 5 to reach a counselor.",
    }),
    Object.freeze({
      name: "Emergency services",
      contact: "Call 911 if you are in immediate danger.",
    }),
  ]),
});

// A statement of intent, then up to three words, before a harm verb. "have" is
// excluded from the gap so "I might have hurt myself at the gym" is not a
// match.
const INTENT =
  "(?:want|wanted|wanna|going|gonna|plan|planning|might|may|could|need|try|trying|tried|thinking|thought|thoughts|urge|urges|feel like)";
const GAP = "(?:\\s+(?!have\\b)[\\w']+){0,3}\\s+";

const CRISIS_PATTERNS: RegExp[] = [
  // Suicide and wanting to die.
  /\bsuicid/,
  /\bkill(?:ing)? my ?self\b/,
  /\b(?:end|ending|take|taking) my (?:own )?life\b/,
  /\bend(?:ing)? it all\b/,
  /\b(?:want(?:ed)? to|wanna|wish i could|ready to|going to|gonna) die\b/,
  /\bwish i (?:was|were) (?:dead|never born)\b/,
  /\bbetter off (?:dead|without me)\b/,
  /\b(?:don't|dont|do not) want to (?:live|be alive|exist|wake up|be here any ?more)\b/,
  /\bno (?:reason|point) (?:to|in) (?:live|living|go on|going on)\b/,
  /\bnot worth living\b/,
  /\bcan(?:'t|t|not) (?:go on|keep going|do this) (?:any ?more|like this)\b/,
  // Self-harm.
  /\bself[- ]?harm/,
  /\b(?:hurting|harming|cutting|burning) my ?self\b/,
  new RegExp(
    `\\b${INTENT}${GAP}(?:hurt|harm|cut|injure|burn) my ?self\\b(?! (?:some|a little|a bit of) slack)`,
  ),
  /\b(?:hurt|harm|cut|injure|burn)(?:ed|s)? my ?self on purpose\b/,
  /\boverdos/,
  // Abuse, or harm from or to someone else.
  /\b(?:he|she|they|someone|partner|boyfriend|girlfriend|husband|wife|dad|father|mom|mother|parents?|roommate) (?:keeps? |always |still )?(?:hits?|beats?|beat|hurts?|chokes?|choked) me\b/,
  /\b(?:abus(?:es|ed|ing)|rap(?:es|ed)|molest(?:s|ed)|sexually assault(?:s|ed)) me\b/,
  /\b(?:being|been|was|am|i'm|im|get|getting|got) (?:abused|raped|molested|sexually assaulted)\b/,
  new RegExp(
    `\\b${INTENT}${GAP}(?:kill|hurt|harm|shoot|stab) (?:him|her|them|someone|somebody|everyone|people)\\b`,
  ),
  /\b(?:i'm|im|i am) (?:not safe|in danger)\b/,
  /\bafraid for my life\b/,
];

function normalize(text: string): string {
  return text.toLowerCase().replace(/[‘’]/g, "'").replace(
    /\s+/g,
    " ",
  );
}

export function containsCrisisLanguage(texts: readonly string[]): boolean {
  return texts.some((text) => {
    const normalized = normalize(text);
    return CRISIS_PATTERNS.some((pattern) => pattern.test(normalized));
  });
}
